//! `ngx_http_headers_module`: `add_header`, `add_header_inherit` and `expires`.
//!
//! Responses produced by local modules (static files, `return`, Lua content) pass through the
//! same header chain as proxied responses, so the filter lives here once
//! (`ngx_http_headers_filter`). `expires` is generated by
//! [`crate::modules::expires`] and merged into this configuration, exactly like
//! `ngx_http_headers_conf_t` holds both.

use crate::core::http::RequestStateView;
use crate::core::variables::Template;
use crate::core::{Context, DirectiveSpec, Module, ModuleKind};
use crate::modules::location::LocationConf;
use anyhow::Result;
use http::StatusCode;
use pingora_http::ResponseHeader;

pub const MODULE_NAME: &str = "ngx_http_headers_module";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct HeaderValue {
    pub name: String,
    pub value: Template,
    /// `add_header ... always`: apply regardless of response status.
    pub always: bool,
}

/// `ngx_http_headers_inherit[]`: how a child's `add_header` list combines with its parent's.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Inherit {
    Off,
    #[default]
    On,
    Merge,
}

impl Inherit {
    pub fn parse(value: &str) -> Option<Self> {
        match value {
            "off" => Some(Inherit::Off),
            "on" => Some(Inherit::On),
            "merge" => Some(Inherit::Merge),
            _ => None,
        }
    }
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct HeadersConf {
    pub headers: Vec<HeaderValue>,
    /// `expires …` (`ngx_http_headers_filter_module`).
    pub expires: Option<crate::modules::expires::Expires>,
    /// `add_header_inherit off|on|merge`.
    pub inherit: Inherit,
}

impl LocationConf for HeadersConf {}

impl HeadersConf {
    pub fn is_empty(&self) -> bool {
        self.headers.is_empty() && self.expires.is_none()
    }

    /// Whether the filter has work to do (`ngx_http_headers_filter`'s early exit).
    pub fn active(&self) -> bool {
        !self.headers.is_empty() || self.expires.as_ref().is_some_and(|value| !value.is_off())
    }

    /// Merge a parent configuration into this one (`ngx_http_headers_merge_conf`).
    ///
    /// `child` is the location's own values; `parent` is inherited when the child has no
    /// `add_header` of its own (`on`), always (`merge`), or never (`off`).
    pub fn merged(parent: &HeadersConf, mut child: HeadersConf) -> HeadersConf {
        if child.expires.is_none() {
            child.expires = parent.expires.clone();
        }
        match child.inherit {
            Inherit::Off => {}
            Inherit::On => {
                if child.headers.is_empty() {
                    child.headers = parent.headers.clone();
                }
            }
            Inherit::Merge => {
                if !parent.headers.is_empty() {
                    let mut merged = child.headers.clone();
                    merged.extend(parent.headers.iter().cloned());
                    child.headers = merged;
                }
            }
        }
        child
    }

    /// Add matching headers to a response, following Nginx's status filter
    /// (`200, 201, 204, 206, 301, 302, 303, 304, 307, 308` unless `always`).
    pub fn apply(
        &self,
        response: &mut ResponseHeader,
        view: &RequestStateView,
    ) -> anyhow::Result<()> {
        // `ngx_http_set_expires` runs before the `add_header` loop.
        if let Some(expires) = &self.expires {
            let last_modified = response
                .headers
                .get("last-modified")
                .and_then(|value| value.to_str().ok())
                .and_then(|value| httpdate::parse_http_date(value).ok());
            crate::modules::expires::apply(
                expires,
                response,
                std::time::SystemTime::now(),
                last_modified,
            )?;
        }
        for header in &self.headers {
            if !header.always && !add_header_allowed(response.status) {
                continue;
            }
            let value = header.value.eval_with(&mut |name| view.variable(name));
            // `ngx_http_add_header`: an empty value adds nothing.
            if value.is_empty() {
                continue;
            }
            response.insert_header(header.name.clone(), value)?;
        }
        Ok(())
    }
}

pub fn add_header_allowed(status: StatusCode) -> bool {
    matches!(
        status.as_u16(),
        200 | 201 | 204 | 206 | 301 | 302 | 303 | 304 | 307 | 308
    )
}

pub struct HeadersModule;

impl Module for HeadersModule {
    fn name(&self) -> &'static str {
        MODULE_NAME
    }

    fn kind(&self) -> ModuleKind {
        ModuleKind::Http
    }

    fn directives(&self) -> Vec<DirectiveSpec> {
        vec![
            DirectiveSpec {
                name: "add_header",
                contexts: &[Context::Http, Context::Server, Context::Location],
                handler: parse_add_header,
            },
            DirectiveSpec {
                name: "add_header_inherit",
                contexts: &[Context::Http, Context::Server, Context::Location],
                handler: parse_add_header_inherit,
            },
            DirectiveSpec {
                name: "expires",
                contexts: &[Context::Http, Context::Server, Context::Location],
                handler: parse_expires,
            },
        ]
    }
}

fn parse_add_header(view: &mut crate::modules::DirectiveView<'_>) -> Result<()> {
    let directive = view.directive;
    directive.expect_args_range(2..=3)?;
    let always = match directive.args.get(2).map(String::as_str) {
        None => false,
        Some("always") => true,
        Some(other) => {
            return Err(directive.error(format!("invalid add_header flag {other}")));
        }
    };
    let value = Template::parse(&directive.args[1])
        .map_err(|error| directive.error(format!("invalid add_header value: {error}")))?;
    view.update_conf::<HeadersConf>(|conf| {
        conf.headers.push(HeaderValue {
            name: directive.args[0].clone(),
            value,
            always,
        });
    })
}

fn parse_add_header_inherit(view: &mut crate::modules::DirectiveView<'_>) -> Result<()> {
    let directive = view.directive;
    directive.expect_args(1)?;
    let inherit = Inherit::parse(&directive.args[0])
        .ok_or_else(|| directive.error(format!("invalid value \"{}\"", directive.args[0])))?;
    view.update_conf::<HeadersConf>(|conf| conf.inherit = inherit)
}

/// `ngx_http_headers_expires`: `expires [modified] time;`.
fn parse_expires(view: &mut crate::modules::DirectiveView<'_>) -> Result<()> {
    let directive = view.directive;
    directive.expect_args_range(1..=2)?;
    if view
        .location_conf::<HeadersConf>()
        .is_some_and(|conf| conf.expires.is_some())
    {
        return Err(directive.error("expires is duplicate"));
    }
    let (modified, value) = match directive.args.as_slice() {
        [value] => (false, value.as_str()),
        [keyword, value] if keyword == "modified" => (true, value.as_str()),
        _ => return Err(directive.error("invalid value")),
    };
    let mut error = None;
    let expires = if value.contains('$') {
        // `cv.lengths != NULL`: the value is evaluated per request.
        let base = crate::modules::expires::parse(value, modified, &mut error);
        if let Some(message) = error {
            return Err(directive.error(message));
        }
        let template = Template::parse(value)
            .map_err(|problem| directive.error(format!("invalid expires value: {problem}")))?;
        crate::modules::expires::Expires::Value {
            base: Box::new(base.unwrap_or(crate::modules::expires::Expires::Access(0))),
            template,
        }
    } else {
        let parsed = crate::modules::expires::parse(value, modified, &mut error);
        match parsed {
            Some(parsed) => parsed,
            None => {
                return Err(directive.error(error.unwrap_or_else(|| "invalid value".to_string())));
            }
        }
    };
    view.update_conf::<HeadersConf>(|conf| conf.expires = Some(expires))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn status_filter_matches_nginx() {
        assert!(add_header_allowed(StatusCode::OK));
        assert!(add_header_allowed(StatusCode::NOT_MODIFIED));
        assert!(!add_header_allowed(StatusCode::NOT_FOUND));
        assert!(!add_header_allowed(StatusCode::INTERNAL_SERVER_ERROR));
    }

    #[test]
    fn inherit_modes() {
        let parent = HeadersConf {
            headers: vec![HeaderValue {
                name: "X-Parent".into(),
                value: Template::parse("1").unwrap(),
                always: false,
            }],
            expires: Some(crate::modules::expires::Expires::Max),
            inherit: Inherit::On,
        };
        let child = HeadersConf::default();
        let merged = HeadersConf::merged(&parent, child.clone());
        assert_eq!(merged.headers.len(), 1, "on inherits when the child has none");
        assert!(merged.expires.is_some());

        let own = HeadersConf {
            headers: vec![HeaderValue {
                name: "X-Own".into(),
                value: Template::parse("2").unwrap(),
                always: false,
            }],
            ..HeadersConf::default()
        };
        let merged = HeadersConf::merged(&parent, own.clone());
        assert_eq!(merged.headers.len(), 1, "on keeps only the child's list");

        let mut merge = own.clone();
        merge.inherit = Inherit::Merge;
        let merged = HeadersConf::merged(&parent, merge);
        assert_eq!(merged.headers.len(), 2, "merge appends the parent list");

        let mut off = own;
        off.inherit = Inherit::Off;
        let merged = HeadersConf::merged(&parent, off);
        assert_eq!(merged.headers.len(), 1);
        assert!(merged.expires.is_some(), "expires is independent of add_header");
    }
}
